-- Backlot manual setup, step 00: read-only preflight
--
-- Run in the Supabase SQL Editor before step 01. It only reads; it changes nothing.
-- Every row should say ok (rows marked information always do). If any says FAIL, stop and share the output.
--
-- GENERATED by `node scripts/generate-manual-setup.ts`. Do not edit by hand.
SELECT "check", CASE WHEN ok THEN 'ok' ELSE 'FAIL' END AS result, detail FROM (
  SELECT 1 AS ord, 'running as postgres' AS "check", (current_user = 'postgres') AS ok, (current_user)::text AS detail
UNION ALL
  SELECT 2 AS ord, 'Postgres 15 or newer' AS "check", (current_setting('server_version_num')::int >= 150000) AS ok, (current_setting('server_version'))::text AS detail
UNION ALL
  SELECT 3 AS ord, 'default schema is public' AS "check", (current_schema() = 'public') AS ok, (current_schema())::text AS detail
UNION ALL
  SELECT 4 AS ord, 'legacy tables are in legacy_init (transition done)' AS "check", ((SELECT count(*) FROM information_schema.tables WHERE table_schema = 'legacy_init' AND table_name IN ('channels', 'items', 'files')) = 3) AS ok, ((SELECT count(*) FROM information_schema.tables WHERE table_schema = 'legacy_init' AND table_name IN ('channels', 'items', 'files')) || ' of 3')::text AS detail
UNION ALL
  SELECT 5 AS ord, 'legacy tables are empty' AS "check", (coalesce(CASE WHEN (SELECT count(*) FROM information_schema.tables WHERE table_schema = 'legacy_init' AND table_name IN ('channels', 'items', 'files')) = 3 THEN (xpath('/row/n/text()', query_to_xml('SELECT (SELECT count(*) FROM legacy_init.channels) + (SELECT count(*) FROM legacy_init.items) + (SELECT count(*) FROM legacy_init.files) AS n', false, true, '')))[1]::text::bigint END, -1) = 0) AS ok, (coalesce((CASE WHEN (SELECT count(*) FROM information_schema.tables WHERE table_schema = 'legacy_init' AND table_name IN ('channels', 'items', 'files')) = 3 THEN (xpath('/row/n/text()', query_to_xml('SELECT (SELECT count(*) FROM legacy_init.channels) + (SELECT count(*) FROM legacy_init.items) + (SELECT count(*) FROM legacy_init.files) AS n', false, true, '')))[1]::text::bigint END)::text, 'not checked'))::text AS detail
UNION ALL
  SELECT 6 AS ord, 'no old-design tables left in public' AS "check", (to_regclass('public.items') IS NULL AND to_regclass('public.files') IS NULL AND to_regclass('public.channels') IS NULL) AS ok, (concat_ws(', ', CASE WHEN to_regclass('public.items') IS NOT NULL THEN 'items' END, CASE WHEN to_regclass('public.files') IS NOT NULL THEN 'files' END, CASE WHEN to_regclass('public.channels') IS NOT NULL THEN 'channels' END))::text AS detail
UNION ALL
  SELECT 7 AS ord, 'fresh: none of the 15 Backlot tables or backlot_schema_migrations exist yet' AS "check", ((SELECT string_agg(t, ', ' ORDER BY t) FROM unnest(ARRAY['account_deletions', 'channels', 'content_items', 'ideas', 'slate_action_events', 'slate_actions', 'slate_breaker_state', 'slate_conversations', 'slate_embeddings', 'slate_messages', 'slate_preferences', 'slate_usage_leases', 'upload_sessions', 'uploaded_files', 'users', 'backlot_schema_migrations']::text[]) AS t WHERE to_regclass('public.' || t) IS NOT NULL) IS NULL) AS ok, (coalesce((SELECT string_agg(t, ', ' ORDER BY t) FROM unnest(ARRAY['account_deletions', 'channels', 'content_items', 'ideas', 'slate_action_events', 'slate_actions', 'slate_breaker_state', 'slate_conversations', 'slate_embeddings', 'slate_messages', 'slate_preferences', 'slate_usage_leases', 'upload_sessions', 'uploaded_files', 'users', 'backlot_schema_migrations']::text[]) AS t WHERE to_regclass('public.' || t) IS NOT NULL), 'none'))::text AS detail
UNION ALL
  SELECT 8 AS ord, 'no Backlot index names in use' AS "check", ((SELECT string_agg(indexname || ' on ' || tablename, ', ' ORDER BY indexname) FROM pg_indexes WHERE schemaname = 'public' AND indexname = ANY (ARRAY['account_deletions_due_idx', 'channels_user_idx', 'content_items_user_idx', 'ideas_user_idx', 'slate_action_events_action_idx', 'slate_actions_user_idx', 'slate_conversations_user_idx', 'slate_embeddings_target_uq', 'slate_messages_conversation_seq_uq', 'slate_messages_user_idx', 'slate_preferences_scope_key_uq', 'slate_preferences_user_idx', 'slate_usage_leases_user_idx', 'upload_sessions_status_idx', 'upload_sessions_user_upload_uq', 'uploaded_files_user_idx']::text[])) IS NULL) AS ok, (coalesce((SELECT string_agg(indexname || ' on ' || tablename, ', ' ORDER BY indexname) FROM pg_indexes WHERE schemaname = 'public' AND indexname = ANY (ARRAY['account_deletions_due_idx', 'channels_user_idx', 'content_items_user_idx', 'ideas_user_idx', 'slate_action_events_action_idx', 'slate_actions_user_idx', 'slate_conversations_user_idx', 'slate_embeddings_target_uq', 'slate_messages_conversation_seq_uq', 'slate_messages_user_idx', 'slate_preferences_scope_key_uq', 'slate_preferences_user_idx', 'slate_usage_leases_user_idx', 'upload_sessions_status_idx', 'upload_sessions_user_upload_uq', 'uploaded_files_user_idx']::text[])), 'none'))::text AS detail
UNION ALL
  SELECT 9 AS ord, 'roles backlot_app / backlot_backup not created yet' AS "check", ((SELECT string_agg(rolname, ', ' ORDER BY rolname) FROM pg_roles WHERE rolname IN ('backlot_app', 'backlot_backup')) IS NULL) AS ok, (coalesce((SELECT string_agg(rolname, ', ' ORDER BY rolname) FROM pg_roles WHERE rolname IN ('backlot_app', 'backlot_backup')), 'none'))::text AS detail
UNION ALL
  SELECT 10 AS ord, 'event triggers (information; none expected besides Supabase''s own)' AS "check", (true) AS ok, (coalesce((SELECT string_agg(evtname || ' on ' || evtevent, ', ' ORDER BY evtname) FROM pg_event_trigger), 'none'))::text AS detail
UNION ALL
  SELECT 11 AS ord, 'other schemas (information)' AS "check", (true) AS ok, ((SELECT string_agg(nspname, ', ' ORDER BY nspname) FROM pg_namespace WHERE nspname NOT LIKE 'pg\_%' AND nspname <> 'information_schema'))::text AS detail
) AS checks ORDER BY ord;
